from rewards.gsm8k_reward import _normalize, _NUMBER
from verl.utils.reward_score.math_dapo import last_boxed_only_string, remove_boxed

with open("/workspace/results/run100/rollouts/1.jsonl") as f:
    roll1 = [json.loads(line) for line in f]

by_prompt = defaultdict(list)
for g in roll1:
    by_prompt[g["input"]].append(g)

def extract_final_v2(text: str):
    if not text:
        return None
    tail = text[-300:] if len(text) > 300 else text
    m_hash = re.findall(r"####\s*\$?(-?\d[\d,]*(?:\.\d+)?)", tail)
    if m_hash:
        return _normalize(m_hash[-1])
    b = last_boxed_only_string(tail)
    if b is not None:
        try:
            bnums = _NUMBER.findall(remove_boxed(b))
            if bnums:
                return _normalize(bnums[-1])
        except Exception:
            pass
    lines = [ln.strip() for ln in tail.strip().splitlines() if ln.strip()]
    if lines:
        last_line = lines[-1]
        bolds = re.findall(r"\*\*([^*]+)\*\*", last_line)
        if bolds:
            bnums = _NUMBER.findall(bolds[-1])
            if bnums:
                return _normalize(bnums[-1])
    nums = _NUMBER.findall(tail)
    if nums:
        return _normalize(nums[-1])
    return None

# Compare lengths of positive vs negative rollouts within active prompts under custom vs v2
for name, fn in [
    ("buggy_any_num", lambda g: g["score"]),
    ("final_ans_v2", lambda g: 1.0 if extract_final_v2(g["output"]) == _normalize(str(g["gts"])) else 0.0),
]:
    pos_lens = []
    neg_lens = []
    for p, gs in by_prompt.items():
        scores = [fn(g) for g in gs]
