"""Reward for GSM8K-style problems.

Extracts the final answer from the end of the response (checking explicit ``#### <number>`` markers,
``\\boxed{...}`` expressions, bolded final numbers, or the last number in the tail of the response)
and compares the normalized numerical value against the ground truth.

Wired in through ``reward.custom_reward_function.path/name`` (see run_gsm8k_grpo.sh); verl calls
``compute_score(data_source=..., solution_str=..., ground_truth=..., extra_info=...)`` and uses the
same function for the held-out validation metric.
"""

import re

_NUMBER = re.compile(r"-?\d[\d,]*(?:\.\d+)?")
_HASH_ANSWER = re.compile(r"####\s*\$?(-?\d[\d,]*(?:\.\d+)?)")
_BOXED = re.compile(r"\\boxed\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}")
_BOLD = re.compile(r"\*\*([^*]+)\*\*")
_CLIP_CHARS = 300


def _normalize(num: str) -> str:
    num = num.replace(",", "").replace("$", "").strip().rstrip(".")
    if num.startswith("-"):
        sign, num = "-", num[1:]
    else:
        sign = ""
    num = num.lstrip("0") or "0"
    if "." in num:
        num = num.rstrip("0").rstrip(".") or "0"
    return sign + num


def extract_answer(solution_str: str) -> str | None:
    if not solution_str:
        return None
    tail = solution_str[-_CLIP_CHARS:] if len(solution_str) > _CLIP_CHARS else solution_str

    m_hash = _HASH_ANSWER.findall(tail)
    if m_hash:
        return _normalize(m_hash[-1])

    m_boxed = _BOXED.findall(tail)
    if m_boxed:
        nums = _NUMBER.findall(m_boxed[-1])
        if nums:
            return _normalize(nums[-1])

    lines = [ln.strip() for ln in tail.strip().splitlines() if ln.strip()]
    if lines:
        bolds = _BOLD.findall(lines[-1])
        if bolds:
            nums = _NUMBER.findall(bolds[-1])
            if nums:
                return _normalize(nums[-1])

    nums = _NUMBER.findall(tail)
    if nums:
        return _normalize(nums[-1])

    return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    if solution_str is None:
        return 0.0
    gold = _normalize(str(ground_truth))
    pred = extract_answer(solution_str)
    return 1.0 if pred == gold else 0.0

